const store=new FileStore((status,error)=>{if(status==='saving')$('#save-status').textContent='Salvando…';if(status==='saved'){$('#save-status').textContent='Salvo às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});hideError();}if(status==='error'){$('#save-status').textContent='Falha ao salvar • alterações em memória';showError('Não foi possível gravar o arquivo. Suas alterações continuam nesta sessão. Use “Salvar agora” para tentar novamente. '+error.message);}});
