async function persist(){if(window.desktop)window.desktop.setDirty(true);try{await store.change();if(window.desktop)window.desktop.setDirty(store.dirty||pendingAttachments>0);return true;}catch{return false;}}
function focusPageTop(){$('#main').focus({preventScroll:true});window.scrollTo({top:0,left:0,behavior:'instant'});document.querySelector('.workspace').scrollTop=0;}
