function dropArea(t){const s=limits();return `<div class="drop" data-drop="${esc(t.id)}">Selecione ou arraste arquivos • até ${s.fileLimitMB} MB/arquivo, ${s.taskLimitMB} MB/tarefa.<br>Base64 ocupa aproximadamente 33% a mais no JSON.<input type="file" multiple data-attach="${esc(t.id)}" aria-label="Anexar arquivos a ${esc(t.title)}"></div>`;}
