function filters(statuses=[],priorities=false){return `<div class="filters"><input type="search" id="search" placeholder="Buscar título, contexto ou responsável…" aria-label="Buscar" value="${esc(query)}">${statuses.length?`<select id="status-filter" aria-label="Filtrar status"><option value="">Todos os status</option>${statuses.map(x=>`<option ${statusFilter===x?'selected':''}>${x}</option>`).join('')}</select>`:''}${priorities?`<select id="priority-filter" aria-label="Filtrar prioridade"><option value="">Todas as prioridades</option>${['alta','média','baixa'].map(x=>`<option ${priorityFilter===x?'selected':''}>${x}</option>`).join('')}</select>`:''}<button class="secondary" id="clear-filters">Limpar filtros</button></div>`;}
function matches(t){return [...Object.values(t).filter(x=>typeof x==='string'),...(t.history||[]).map(h=>h.text)].join(' ').toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))&&(!statusFilter||t.status===statusFilter)&&(!priorityFilter||t.priority===priorityFilter);}
