 return `<section class="home-month"><div class="home-section-title"><h2>${esc(current.toLocaleDateString('pt-BR',{month:'long'}))}</h2><button class="home-icon-button" data-nav="calendar" aria-label="Abrir agenda">${uiIcon('arrow')}</button></div><div class="home-month-grid">${['S','T','Q','Q','S','S','D'].map((day,i)=>`<span class="home-weekday" aria-label="${['segunda','terça','quarta','quinta','sexta','sábado','domingo'][i]}">${day}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:total},(_,i)=>{const date=today(new Date(year,month,i+1)),count=itemsForDay(data(),date).length;return `<button data-home-day="${date}" class="${date===today()?'home-today':''} ${date===(homeDate||today())?'home-selected':''} ${count?'home-has-events':''}" aria-pressed="${date===(homeDate||today())}" aria-label="${i+1} de ${esc(current.toLocaleDateString('pt-BR',{month:'long'}))}${count?', '+count+' compromisso(s)':''}" ${date===today()?'aria-current="date"':''}>${i+1}</button>`;}).join('')}</div></section>`;
