 menu=`<details class="task-action-menu"><summary aria-label="Ações de ${esc(item.title)}">⋯</summary><div class="task-action-options"><button data-edit="${kind}" data-id="${esc(item.id)}">Editar</button>${kind==='topics'?`<button data-work-update="${esc(item.id)}" data-collection="topics">Adicionar atualização</button><button data-resolve="${esc(item.id)}">Encerrar assunto</button>`:''}<button class="task-action-delete" data-delete="${kind}" data-id="${esc(item.id)}">Excluir</button></div></details>`;
