function field(name,label,type='text',value='',options=null,required=false){return `<label class="${type==='textarea'?'wide':''}">${label}${required?' *':''}${options?`<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${name==='title'?'maxlength="300"':''}>`}</label>`;}
function scheduleFields(title,dateKey,date,timeKey,time){return `<fieldset class="schedule-fields wide"><legend>${esc(title)} · data e hora</legend><div>${field(dateKey,'Data','date',date||'')}${field(timeKey,'Hora','time',time||'')}</div><p>Defina a hora para receber alertas. Sem hora, o item permanece apenas com a data.</p></fieldset>`;}
function openEditor(kind,item=null,preset={}){if(kind==='tasks'&&item)activeTask=item.id;if(kind==='topics'&&item)activeSubject='topic:'+item.id;if(kind==='decisions')return;const t=item||preset;editorState={kind,item,sourceFeedbackId:preset.sourceFeedbackId||null,sourceIdeaId:preset.sourceIdeaId||null};$('#dialog-title').textContent=(item?'Editar ':'Criar ')+({tasks:'tarefa',topics:'assunto',routines:'bloco recorrente',ideas:'registro',feedbacks:'feedback'}[kind]);let html=field('title','Título','text',t.title||'',null,true);
 if(kind==='tasks')html+=scheduleFields('Prazo da tarefa','due',t.due,'dueTime',t.dueTime)+field('description','Descrição / próximo passo','textarea',t.description||'')+field('topicId','Assunto vinculado (opcional)','text',t.topicId||'',[['','Sem assunto'],...data().topics.map(topic=>[topic.id,topic.title]),...(t.topicId&&!data().topics.some(topic=>topic.id===t.topicId)?[[t.topicId,'Assunto não encontrado · escolha outro']]:[])])+field('project','Área / projeto','text',t.project||'')+field('owner','Responsável','text',t.owner||'')+field('priority','Prioridade','text',t.priority||'média',['alta','média','baixa'].map(s=>[s,s]))+field('status','Status','text',t.status||'aberto',['aberto','em andamento','concluído'].map(s=>[s,s==='aberto'?'Em aberto':s==='concluído'?'Concluída':'Em andamento']));
 if(kind==='tasks')html+=field('feedbackId','Feedback vinculado (opcional)','text',t.feedbackId||'',[['','Sem feedback'],...(data().feedbacks||[]).map(f=>[f.id,f.person+' · '+f.title])]);
 if(kind==='topics')html+=field('nextStep','Qual é o próximo passo?','textarea',t.nextStep||'')+field('status','Como está?','text',t.status||'acompanhar',[[t.status==='em andamento'?'em andamento':'acompanhar','Em aberto'],['aguardando','Aguardando resposta'],['resolvido','Resolvido']])+field('owner','Quem está cuidando?','text',t.owner||'')+scheduleFields('Quando voltar a este assunto?','review',t.review,'reviewTime',t.reviewTime)+`<details class="wide optional-fields"><summary>Adicionar contexto (opcional)</summary>`+field('context','O que preciso lembrar?','textarea',t.context||'')+'</details>';

 if(kind==='feedbacks')html+=field('direction','Direção','text',t.direction||(feedbackView==='received'?'received':'share'),[['share','A compartilhar'],['received','Recebidos']])+field('person','Pessoa','text',t.person||'',null,true)+field('relationship','Relação / papel','text',t.relationship||'Time',[['Time','Time'],['PM','PM'],['PA','PA'],['Liderança','Liderança'],['Outra pessoa','Outra pessoa']])+field('status','Etapa','text',t.status||(feedbackView==='received'?'refletir':'preparar'),Object.entries(feedbackStatuses))+field('date','Data da conversa (opcional)','date',t.date||'')+field('context','Situação / contexto','textarea',t.context||'')+field('content','Comportamento observado e impacto','textarea',t.content||'')+field('nextStep','Próximo passo / combinado','textarea',t.nextStep||'')+scheduleFields('Quando retomar este feedback?','review',t.review,'reviewTime',t.reviewTime);
 if(kind==='ideas')html+=field('content','Contexto inicial / detalhes','textarea',t.content||'');
 if(kind==='routines')html+=`<p class="wide muted">Repete toda semana no dia escolhido. Editar ou excluir este bloco altera todas as suas ocorrências.</p>`+field('day','Dia da semana','text',t.day??1,['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'].map((s,i)=>[i,s]))+field('time','Horário','time',t.time||'09:00',null,true)+field('note','Observação','textarea',t.note||'');
 if(page==='calendar'&&kind==='tasks'){const labelAt=html.indexOf('Assunto vinculado (opcional)'),extraAt=html.lastIndexOf('<label',labelAt);if(extraAt>=0)html=html.slice(0,extraAt)+'<details class="studio-editor-extra wide"><summary>Mais detalhes · projeto, responsável e prioridade</summary><div>'+html.slice(extraAt)+'</div></details>';}
 $('#fields').innerHTML=html;$('#form-error').textContent='';$('#editor').showModal();$('#fields input').focus();}
$('#edit-form').onsubmit=async e=>{e.preventDefault();const {kind,item,sourceIdeaId,sourceFeedbackId,collection='ideas'}=editorState;const values=Object.fromEntries(new FormData(e.target));for(const key in values)values[key]=values[key].trim();if(kind==='linkFeedbackTask'){const task=data().tasks.find(t=>t.id===values.taskId);if(!task||!(data().feedbacks||[]).includes(item)){$('#form-error').textContent='Escolha uma tarefa e um feedback válidos.';return;}linkTaskToFeedback(task,item);$('#editor').close();render();await persist();return;}if(kind==='linkTask'){const task=data().tasks.find(t=>t.id===values.taskId);if(!task||!data().topics.includes(item)){$('#form-error').textContent='Escolha uma tarefa e um assunto válidos.';return;}linkTaskToTopic(task,item.id);activeSubject='topic:'+item.id;$('#editor').close();render();await persist();return;}if(kind==='recordUpdate'){if(!values.content){$('#form-error').textContent='Escreva a atualização.';return;}if(!data()[collection]?.includes(item)){ $('#form-error').textContent='Este registro não está mais disponível.';return;}appendHistory(item,values.content);$('#editor').close();render();await persist();return;}if(!values.title){$('#form-error').textContent='Informe um título.';return;}for(const [timeKey,dateKey] of [['dueTime','due'],['reviewTime','review'],['dateTime','date']])if(values[timeKey]&&!values[dateKey]){$('#form-error').textContent='Informe a data correspondente ao horário.';return;}if(kind==='decisions'&&values.topicId&&!data().topics.some(t=>t.id===values.topicId)){$('#form-error').textContent='Escolha um assunto existente.';return;}if(kind==='tasks'&&values.topicId&&!data().topics.some(t=>t.id===values.topicId)){$('#form-error').textContent='Escolha um assunto existente ou Sem assunto.';return;}if(kind==='tasks'&&values.feedbackId&&!(data().feedbacks||[]).some(f=>f.id===values.feedbackId)){$('#form-error').textContent='Escolha um feedback existente.';return;}if(kind==='feedbacks'&&!values.person){$('#form-error').textContent='Informe a pessoa do feedback.';return;}if(kind==='ideas')values.recordType=item?.recordType||'idea';if(kind==='routines')values.day=Number(values.day);const timestamp=now();if(item){if(kind==='tasks'&&values.topicId!==undefined)linkTaskToTopic(item,values.topicId);if(['tasks','topics','feedbacks'].includes(kind)){const names={title:'Título',description:'Descrição / próximo passo',project:'Projeto',owner:'Responsável',due:'Prazo',dueTime:'Hora do prazo',reviewTime:'Hora da revisão',dateTime:'Hora da decisão',priority:'Prioridade',status:'Status',context:'Contexto',nextStep:'Próximo passo',review:'Data de revisão',date:'Data da decisão',alternatives:'Alternativas',decision:'Decisão tomada',topicId:'Assunto vinculado',decisionState:'Decisão pendente'};const changes=Object.entries(values).filter(([key,value])=>(item[key]??'')!==value).map(([key,value])=>`${names[key]||key}: ${item[key]||'não informado'} → ${value||'não informado'}`);if(changes.length)appendHistory(item,'Registro editado.\n'+changes.join('\n'));}Object.assign(item,values,{updatedAt:timestamp});}else{const record={id:id(),...values,createdAt:timestamp,updatedAt:timestamp};if(kind==='tasks'){record.attachments=[];if(sourceIdeaId)record.sourceIdeaId=sourceIdeaId;if(sourceFeedbackId)record.feedbackId=sourceFeedbackId;}if(['tasks','topics','feedbacks'].includes(kind))record.history=[{id:id(),at:timestamp,text:kind==='tasks'?'Tarefa criada.':kind==='topics'?'Assunto registrado.':'Feedback registrado.'}];data()[kind]??=[];data()[kind].push(record);if(kind==='tasks'&&record.topicId){const topic=data().topics.find(t=>t.id===record.topicId);if(topic)appendHistory(topic,'Tarefa criada: '+record.title);}if(kind==='tasks'){activeTask=record.id;taskView=record.status==='concluído'?'done':'open';}if(kind==='topics'){activeSubject='topic:'+record.id;subjectView=record.status==='resolvido'?'done':'open';}}if(kind==='feedbacks')feedbackView=values.direction;$('#editor').close();if(page==='calendar'&&['tasks','topics','decisions','routines'].includes(kind))agendaType={tasks:'task',topics:'topic',decisions:'decision',routines:'routine'}[kind];render();await persist();};
for(const b of document.querySelectorAll('.close'))b.onclick=()=>$('#editor').close();
