 document.querySelectorAll('[data-toggle]').forEach(b=>b.onchange=async()=>{const t=data().tasks.find(t=>t.id===b.dataset.toggle);t.status=b.checked?'concluído':'aberto';appendHistory(t,'Status: '+t.status);render();await persist();});
