 if($('#suggest-routines'))$('#suggest-routines').onclick=async()=>{const suggestions=[[1,'09:00','Revisão de bloqueios','Sugestão: ajuste a frequência ao time.'],[2,'10:00','Foco protegido','Reserve um bloco para trabalho profundo.'],[1,'14:00','Prioridades, riscos e dependências','Revise a semana com o time.'],[4,'14:00','Acompanhamento individual','Espaço para escuta e desenvolvimento.']];for(const [day,time,title,note] of suggestions)if(!data().routines.some(r=>r.title===title))data().routines.push({id:id(),day,time,title,note});render();await persist();};
 bindAttachments();if(page==='calendar'){bindPlanner();bindCalendar();}
