 return `<section class="studio-timeline calendar-surface" aria-label="Calendário ${mode==='day'?'diário':'semanal'}"><div id="agenda-time-scroll" class="studio-time-scroll"><div class="studio-time-inner ${mode}" style="--studio-days:${days.length}"><div class="studio-time-header"><span class="studio-timezone" title="${esc(localTZ)}">${esc(timezone)}</span>${headings}</div><div class="studio-anytime"><span>Sem horário<br>ou dia inteiro</span>${anytime}</div><div class="studio-hours"><div class="studio-hour-axis">${Array.from({length:24},(_,h)=>`<span style="top:${h*76}px">${String(h).padStart(2,'0')}:00</span>`).join('')}${days.includes(today())?`<span class="studio-now-label" style="top:${nowMinute*76/60}px">${nowDate.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span>`:''}</div><div class="calendar-board ${mode} studio-time-columns">${days.map(day=>{
 const rows=agendaTimelineLayout(agendaItems(day),day);
 return `<section class="studio-time-day ${day===today()?'is-today':''}" aria-label="${day}"><div class="studio-time-slots">${Array.from({length:48},(_,n)=>{const time=String(Math.floor(n/2)).padStart(2,'0')+':'+(n%2?'30':'00');return `<button data-create-slot="${day}" data-slot-time="${time}" aria-label="Criar tarefa em ${day} às ${time}"><span>+ ${time}</span></button>`;}).join('')}</div><div class="studio-event-layer">${rows.map(row=>studioEventCard(row.item,day,`style="top:${Math.min(row.minute*76/60,1824-76)}px;height:${Math.max(71,(row.visualEnd-row.minute)*76/60-5)}px;left:calc(${row.lane/row.lanes*100}% + 5px);width:calc(${100/row.lanes}% - 10px)"`)).join('')}</div>${day===today()?`<div class="studio-now-line" style="top:${nowMinute*76/60}px"><i></i></div>`:''}</section>`;
 }).join('')}</div></div></div></div><div class="studio-grid-foot">Clique em um horário para criar · Clique em um cartão para abrir · Blocos e prazos indicam apenas o início</div></section>`;
