 $('#test-desktop-notification').onclick=async()=>{try{if(window.desktop)await permitDesktopNotifications();const desktopPosition=$('#reminder-position').value,desktopDuration=Number($('#reminder-duration').value);if(!['center','top-right','bottom-right','top-left','bottom-left'].includes(desktopPosition)||!Number.isInteger(desktopDuration)||desktopDuration<3||desktopDuration>120)throw Error('Escolha a posição e um tempo de 3 a 120 segundos.');if(!window.desktop)previewWebAlert({position:desktopPosition,duration:desktopDuration});if(window.desktop||(typeof Notification!=='undefined'&&Notification.permission==='granted'))sendDesktopNotification('Techlead Desk — teste de notificação',{body:'Seus alertas também aparecerão aqui, na área de trabalho.',tag:'techlead-desk-test'},{desktopPosition,desktopDuration});reminderFeedback(window.desktop?'Cartão desktop enviado. Você pode abri-lo sem sair do que está fazendo.':'Prévia exibida na página. Para receber também os avisos do Chrome, use Permitir notificações.');}catch(e){reminderFeedback(e.message);}};
